/* ----------------------------------------------------------------------------
   CATALOGO — lo que la web publica
   ----------------------------------------------------------------------------
   PRODUCTS es el archivo COMPLETO: incluye lo retirado, para poder recuperarlo.
   CATALOGO es lo que se ve. Toda la web (catálogo, buscador, menús, landings,
   carrito) usa CATALOGO; PRODUCTS solo sirve para saber qué hay guardado.

   Para retirar algo: añádele "activo": false.
   Para volver a publicarlo: cámbialo a true o borra el campo.
   -------------------------------------------------------------------------- */
const CATALOGO = PRODUCTS.filter((p) => p.activo !== false);

